// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract EVOLVE is ERC20, ERC20Burnable, ERC20Pausable, AccessControl {
    uint256 public immutable MAX_SUPPLY;
    uint256 public totalMinted;

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    event MaxSupplySet(uint256 maxSupply);

    error MaxSupplyExceeded();

    constructor(address initialOwner, uint256 maxSupply)
        ERC20("EVOLVE", "EVOLVE")
        AccessControl()
    {
        // Default max supply: 8 000 000 000 (8 billion) tokens with 18 decimals
        MAX_SUPPLY = maxSupply > 0 ? maxSupply : 8_000_000_000 * 10**18;
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(MINTER_ROLE, initialOwner);
        emit MaxSupplySet(MAX_SUPPLY);
    }

    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        if (totalMinted + amount > MAX_SUPPLY) revert MaxSupplyExceeded();
        totalMinted += amount;
        _mint(to, amount);
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    function _update(address from, address to, uint256 value)
        internal
        override(ERC20, ERC20Pausable)
    {
        super._update(from, to, value);
    }
}

src/Evolve2Earn.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./EVOLVE.sol";

contract Evolve2Earn is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for EVOLVE;

    EVOLVE public immutable evolveToken;

    uint256 public constant EMOJI_GIFT_PRICE = 1e18;
    uint256 public constant MAX_GIFT_OWNERS = 1000;

    mapping(address => bool) public verified;

    mapping(bytes32 => address) public emojiOwner;
    mapping(address => uint256) public ownerGiftCount;
    address[] public giftOwners;
    mapping(address => bool) private isGiftOwner;
    uint256 public totalGifts;

    // ──────────────────────────────────────────────
    //  P2P TOKEN MARKETPLACE
    // ──────────────────────────────────────────────

    enum OrderStatus { Active, Filled, Cancelled }

    struct TokenOrder {
        uint256 id;
        address seller;
        uint256 evolveAmount;      // Amount of EVOLVE tokens offered
        address tokenAddress;      // Token to receive (ETH = address(0))
        uint256 tokenAmount;       // Amount of token requested
        uint256 networkId;         // Network ID (1=ETH, 56=BNB, 137=POLYGON, etc.)
        OrderStatus status;
        uint256 createdAt;
        string metadata;           // Optional metadata (IPFS hash, etc.)
    }

    mapping(uint256 => TokenOrder) public orders;
    mapping(address => uint256[]) public userOrders;
    uint256 private _nextOrderId;

    // Supported networks
    mapping(uint256 => bool) public supportedNetworks;
    uint256[] public networkIds;

    event UserVerified(address indexed user);
    event EmojiGiftBought(bytes32 indexed emojiId, address indexed owner, uint256 price);
    event EmojiGiftTransferred(bytes32 indexed emojiId, address indexed from, address indexed to);
    event EmojiRevenueDistributed(address indexed buyer, uint256 totalAmount, address[] recipients, uint256[] amounts);
    event OrderCreated(uint256 indexed orderId, address indexed seller, uint256 evolveAmount, address tokenAddress, uint256 tokenAmount, uint256 networkId);
    event OrderFilled(uint256 indexed orderId, address indexed buyer, uint256 evolveAmount, uint256 tokenAmount);
    event OrderCancelled(uint256 indexed orderId);
    event NetworkAdded(uint256 indexed networkId);
    event NetworkRemoved(uint256 indexed networkId);

    error AlreadyVerified();
    error EmojiAlreadyOwned();
    error EmojiNotFound();
    error NotEmojiOwner();
    error ZeroAddress();
    error TransferToSelf();
    error MaxGiftOwnersReached();
    error InvalidNetwork();
    error NetworkNotSupported();
    error OrderNotActive();
    error NotOrderSeller();
    error InsufficientBalance();
    error InvalidAmount();
    error CannotBuyOwnOrder();

    constructor(address initialOwner, address _evolveTokenAddress) Ownable(initialOwner) {
        evolveToken = EVOLVE(_evolveTokenAddress);
        // Initialize default supported networks
        _addDefaultNetworks();
    }

    function _addDefaultNetworks() private {
        // Ethereum Mainnet
        supportedNetworks[1] = true;
        networkIds.push(1);
        // BNB Chain
        supportedNetworks[56] = true;
        networkIds.push(56);
        // Polygon
        supportedNetworks[137] = true;
        networkIds.push(137);
        // Arbitrum
        supportedNetworks[42161] = true;
        networkIds.push(42161);
        // Avalanche
        supportedNetworks[43114] = true;
        networkIds.push(43114);
        // Optimism
        supportedNetworks[10] = true;
        networkIds.push(10);
        // Tron (mapped to EVM compatible)
        supportedNetworks[19] = true;
        networkIds.push(19);
        // Solana (mapped to EVM compatible)
        supportedNetworks[900000] = true;
        networkIds.push(900000);
    }

    function verifyUser(address user) external onlyOwner nonReentrant whenNotPaused {
        if (verified[user]) revert AlreadyVerified();
        verified[user] = true;
        emit UserVerified(user);
    }

    function buyEmojiGift(bytes32 emojiId) external nonReentrant whenNotPaused {
        if (emojiOwner[emojiId] != address(0)) revert EmojiAlreadyOwned();

        evolveToken.safeTransferFrom(msg.sender, address(this), EMOJI_GIFT_PRICE);

        address[] memory recipients;
        uint256[] memory amounts;
        uint256 currentTotal = totalGifts;
        if (currentTotal > 0) {
            (recipients, amounts) = _distributeEmojiRevenue(currentTotal);
        }

        emojiOwner[emojiId] = msg.sender;
        ownerGiftCount[msg.sender] += 1;
        if (!isGiftOwner[msg.sender] && giftOwners.length >= MAX_GIFT_OWNERS) revert MaxGiftOwnersReached();
        if (!isGiftOwner[msg.sender]) {
            isGiftOwner[msg.sender] = true;
            giftOwners.push(msg.sender);
        }
        totalGifts += 1;

        emit EmojiGiftBought(emojiId, msg.sender, EMOJI_GIFT_PRICE);
        if (recipients.length > 0) {
            emit EmojiRevenueDistributed(msg.sender, EMOJI_GIFT_PRICE, recipients, amounts);
        }
    }

    function transferEmojiGift(bytes32 emojiId, address to) external nonReentrant whenNotPaused {
        address from = emojiOwner[emojiId];
        if (from == address(0)) revert EmojiNotFound();
        if (from != msg.sender) revert NotEmojiOwner();
        if (to == address(0)) revert ZeroAddress();
        if (to == from) revert TransferToSelf();

        emojiOwner[emojiId] = to;
        ownerGiftCount[from] -= 1;
        ownerGiftCount[to] += 1;

        if (ownerGiftCount[from] == 0 && isGiftOwner[from]) {
            isGiftOwner[from] = false;
            for (uint256 i = 0; i < giftOwners.length; i++) {
                if (giftOwners[i] == from) {
                    giftOwners[i] = giftOwners[giftOwners.length - 1];
                    giftOwners.pop();
                    break;
                }
            }
        }

        if (!isGiftOwner[to] && giftOwners.length >= MAX_GIFT_OWNERS) revert MaxGiftOwnersReached();
        if (!isGiftOwner[to]) {
            isGiftOwner[to] = true;
            giftOwners.push(to);
        }

        emit EmojiGiftTransferred(emojiId, from, to);
    }

    function getGiftOwners() external view returns (address[] memory) {
        return giftOwners;
    }

    function getOwnerMarketShare(address owner) external view returns (uint256) {
        if (totalGifts == 0) return 0;
        return (ownerGiftCount[owner] * 1e18) / totalGifts;
    }

    function previewDistribution(address exclude) external view returns (address[] memory recipients, uint256[] memory amounts) {
        uint256 currentTotal = totalGifts;
        if (currentTotal == 0) {
            return (new address[](0), new uint256[](0));
        }

        uint256 activeOwnerCount = 0;
        for (uint256 i = 0; i < giftOwners.length; i++) {
            if (ownerGiftCount[giftOwners[i]] > 0 && giftOwners[i] != exclude) {
                activeOwnerCount++;
            }
        }

        recipients = new address[](activeOwnerCount);
        amounts = new uint256[](activeOwnerCount);
        uint256 idx = 0;
        for (uint256 i = 0; i < giftOwners.length; i++) {
            address owner = giftOwners[i];
            if (owner == exclude) continue;
            uint256 count = ownerGiftCount[owner];
            if (count > 0) {
                recipients[idx] = owner;
                amounts[idx] = (count * EMOJI_GIFT_PRICE) / currentTotal;
                idx++;
            }
        }
    }

    // ──────────────────────────────────────────────
    //  P2P MARKETPLACE FUNCTIONS
    // ──────────────────────────────────────────────

    function createOrder(
        uint256 evolveAmount,
        address tokenAddress,
        uint256 tokenAmount,
        uint256 networkId,
        string calldata metadata
    ) external nonReentrant whenNotPaused returns (uint256) {
        if (evolveAmount == 0 || tokenAmount == 0) revert InvalidAmount();
        if (!supportedNetworks[networkId]) revert NetworkNotSupported();

        uint256 balance = evolveToken.balanceOf(msg.sender);
        if (balance < evolveAmount) revert InsufficientBalance();

        // Transfer EVOLVE to contract as escrow
        evolveToken.safeTransferFrom(msg.sender, address(this), evolveAmount);

        uint256 orderId = _nextOrderId++;
        orders[orderId] = TokenOrder({
            id: orderId,
            seller: msg.sender,
            evolveAmount: evolveAmount,
            tokenAddress: tokenAddress,
            tokenAmount: tokenAmount,
            networkId: networkId,
            status: OrderStatus.Active,
            createdAt: block.timestamp,
            metadata: metadata
        });

        userOrders[msg.sender].push(orderId);
        emit OrderCreated(orderId, msg.sender, evolveAmount, tokenAddress, tokenAmount, networkId);
        return orderId;
    }

    function fillOrder(uint256 orderId) external payable nonReentrant whenNotPaused {
        TokenOrder storage order = orders[orderId];
        if (order.status != OrderStatus.Active) revert OrderNotActive();
        if (order.seller == msg.sender) revert CannotBuyOwnOrder();

        // Transfer EVOLVE from contract to buyer
        evolveToken.safeTransfer(msg.sender, order.evolveAmount);

        // Transfer payment to seller
        if (order.tokenAddress == address(0)) {
            // Native ETH payment
            if (msg.value < order.tokenAmount) revert InsufficientBalance();
            (bool success, ) = order.seller.call{value: order.tokenAmount}("");
            require(success, "ETH transfer failed");
        } else {
            // ERC20 token payment - buyer must approve this contract first
            IERC20 token = IERC20(order.tokenAddress);
            uint256 balance = token.balanceOf(msg.sender);
            if (balance < order.tokenAmount) revert InsufficientBalance();
            token.transferFrom(msg.sender, order.seller, order.tokenAmount);
        }

        order.status = OrderStatus.Filled;
        emit OrderFilled(orderId, msg.sender, order.evolveAmount, order.tokenAmount);
    }

    function cancelOrder(uint256 orderId) external nonReentrant whenNotPaused {
        TokenOrder storage order = orders[orderId];
        if (order.status != OrderStatus.Active) revert OrderNotActive();
        if (order.seller != msg.sender) revert NotOrderSeller();

        // Return EVOLVE to seller
        evolveToken.safeTransfer(msg.sender, order.evolveAmount);
        order.status = OrderStatus.Cancelled;
        emit OrderCancelled(orderId);
    }

    function addNetwork(uint256 networkId) external onlyOwner {
        if (!supportedNetworks[networkId]) {
            supportedNetworks[networkId] = true;
            networkIds.push(networkId);
            emit NetworkAdded(networkId);
        }
    }

    function removeNetwork(uint256 networkId) external onlyOwner {
        if (supportedNetworks[networkId]) {
            supportedNetworks[networkId] = false;
            // Remove from array
            for (uint256 i = 0; i < networkIds.length; i++) {
                if (networkIds[i] == networkId) {
                    networkIds[i] = networkIds[networkIds.length - 1];
                    networkIds.pop();
                    break;
                }
            }
            emit NetworkRemoved(networkId);
        }
    }

    function getOrdersBySeller(address seller) external view returns (uint256[] memory) {
        return userOrders[seller];
    }

    function getActiveOrders() external view returns (uint256[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < _nextOrderId; i++) {
            if (orders[i].status == OrderStatus.Active) count++;
        }

        uint256[] memory result = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < _nextOrderId; i++) {
            if (orders[i].status == OrderStatus.Active) {
                result[idx] = i;
                idx++;
            }
        }
        return result;
    }

    function getOrdersByNetwork(uint256 networkId) external view returns (uint256[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < _nextOrderId; i++) {
            if (orders[i].status == OrderStatus.Active && orders[i].networkId == networkId) count++;
        }

        uint256[] memory result = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < _nextOrderId; i++) {
            if (orders[i].status == OrderStatus.Active && orders[i].networkId == networkId) {
                result[idx] = i;
                idx++;
            }
        }
        return result;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function getBalance() external view returns (uint256) {
        return evolveToken.balanceOf(address(this));
    }

    function _distributeEmojiRevenue(uint256 currentTotal) internal returns (address[] memory recipients, uint256[] memory amounts) {
        uint256 activeOwnerCount = 0;
        for (uint256 i = 0; i < giftOwners.length; i++) {
            if (ownerGiftCount[giftOwners[i]] > 0 && giftOwners[i] != msg.sender) {
                activeOwnerCount++;
            }
        }

        recipients = new address[](activeOwnerCount);
        amounts = new uint256[](activeOwnerCount);
        uint256 distributed = 0;
        uint256 idx = 0;

        for (uint256 i = 0; i < giftOwners.length; i++) {
            address owner = giftOwners[i];
            if (owner == msg.sender) continue;
            uint256 count = ownerGiftCount[owner];
            if (count > 0) {
                uint256 share = (count * EMOJI_GIFT_PRICE) / currentTotal;
                recipients[idx] = owner;
                amounts[idx] = share;
                idx++;
                if (share > 0 && evolveToken.balanceOf(address(this)) >= share) {
                    evolveToken.safeTransfer(owner, share);
                    distributed += share;
                }
            }
        }

        if (distributed > 0 && distributed < EMOJI_GIFT_PRICE && evolveToken.balanceOf(address(this)) > 0) {
            uint256 dust = EMOJI_GIFT_PRICE - distributed;
            uint256 contractBalance = evolveToken.balanceOf(address(this));
            if (dust > contractBalance) dust = contractBalance;
            if (dust > 0) {
                evolveToken.safeTransfer(msg.sender, dust);
            }
        }
    }
}

src/EvolveFund.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract EvolveFund is Ownable, ReentrancyGuard {
    IERC20 public immutable evolveToken;

    uint256 public constant MIN_DEPOSIT = 15 * 10**18;
    uint256 public constant MIN_DURATION = 30 days;
    uint256 public constant MIN_EXTENSION = 7 days;

    // Deposit types: Conception (Зачаття) and PostCopulation (Посткопуляція)
    enum DepositType { Conception, PostCopulation }

    struct StakeInfo {
        uint256 amount;
        uint256 unlockTime;
        bool exists;
        DepositType depositType;
    }

    // Women can set different requirements for each deposit type
    struct WomanRequirements {
        uint256 conceptionRequired;    // Min EVOLVE needed for Conception
        uint256 postCopulationRequired; // Min EVOLVE needed for PostCopulation
        bool exists;
    }

    mapping(address => StakeInfo) public stakes;
    mapping(address => StakeInfo) public postCopulationStakes; // Separate stake for PostCopulation
    mapping(address => bool) public lockedByBond;

    // Women's requirements for each mode
    mapping(address => WomanRequirements) public womanRequirements;

    address public bondManager;

    event Deposited(address indexed user, uint256 amount, uint256 unlockTime, DepositType depositType);
    event Withdrawn(address indexed user, uint256 amount, DepositType depositType);
    event Extended(address indexed user, uint256 newUnlockTime, DepositType depositType);
    event Locked(address indexed user, DepositType depositType);
    event Unlocked(address indexed user, DepositType depositType);
    event StakeTransferred(address indexed from, address indexed to, uint256 amount, DepositType depositType);
    event BondManagerSet(address indexed manager);
    event WomanRequirementsSet(address indexed woman, uint256 conceptionRequired, uint256 postCopulationRequired);

    error BelowMinimum();
    error DurationTooShort();
    error NotUnlockedYet();
    error NoStake();
    error LockedByBond();
    error NotBondManager();
    error TransferFailed();
    error InsufficientStake();
    error InvalidDepositType();
    error InsufficientForRequirements();

    modifier onlyBondManager() {
        if (msg.sender != bondManager) revert NotBondManager();
        _;
    }

    constructor(address _evolveToken, address initialOwner) Ownable(initialOwner) {
        evolveToken = IERC20(_evolveToken);
    }

    function setBondManager(address manager) external onlyOwner {
        bondManager = manager;
        emit BondManagerSet(manager);
    }

    // Women set their requirements for each mode
    function setWomanRequirements(uint256 conceptionRequired, uint256 postCopulationRequired) external {
        womanRequirements[msg.sender] = WomanRequirements({
            conceptionRequired: conceptionRequired,
            postCopulationRequired: postCopulationRequired,
            exists: true
        });
        emit WomanRequirementsSet(msg.sender, conceptionRequired, postCopulationRequired);
    }

    function deposit(uint256 amount, uint256 duration, DepositType depositType) external nonReentrant {
        if (amount < MIN_DEPOSIT) revert BelowMinimum();
        if (duration < MIN_DURATION) revert DurationTooShort();

        StakeInfo storage s = depositType == DepositType.Conception ? stakes[msg.sender] : postCopulationStakes[msg.sender];
        uint256 unlock = block.timestamp + duration;

        if (s.exists) {
            s.amount += amount;
            if (unlock > s.unlockTime) s.unlockTime = unlock;
        } else {
            s.amount = amount;
            s.unlockTime = unlock;
            s.exists = true;
            s.depositType = depositType;
        }

        if (!evolveToken.transferFrom(msg.sender, address(this), amount)) revert TransferFailed();
        emit Deposited(msg.sender, amount, unlock, depositType);
    }

    function extend(uint256 additionalDuration, DepositType depositType) external {
        StakeInfo storage s = depositType == DepositType.Conception ? stakes[msg.sender] : postCopulationStakes[msg.sender];
        if (!s.exists) revert NoStake();
        if (additionalDuration < MIN_EXTENSION) revert InsufficientStake();
        s.unlockTime += additionalDuration;
        emit Extended(msg.sender, s.unlockTime, depositType);
    }

    function withdraw(DepositType depositType) external nonReentrant {
        StakeInfo storage s = depositType == DepositType.Conception ? stakes[msg.sender] : postCopulationStakes[msg.sender];
        if (!s.exists) revert NoStake();
        if (block.timestamp < s.unlockTime) revert NotUnlockedYet();
        if (lockedByBond[msg.sender]) revert LockedByBond();

        uint256 amount = s.amount;
        if (depositType == DepositType.Conception) {
            delete stakes[msg.sender];
        } else {
            delete postCopulationStakes[msg.sender];
        }

        if (!evolveToken.transfer(msg.sender, amount)) revert TransferFailed();
        emit Withdrawn(msg.sender, amount, depositType);
    }

    function lockStake(address user, DepositType depositType) external onlyBondManager {
        lockedByBond[user] = true;
        emit Locked(user, depositType);
    }

    function unlockStake(address user, DepositType depositType) external onlyBondManager {
        lockedByBond[user] = false;
        emit Unlocked(user, depositType);
    }

    function bondWithdraw(address user, uint256 amount, address to, DepositType depositType) external onlyBondManager nonReentrant {
        StakeInfo storage s = depositType == DepositType.Conception ? stakes[user] : postCopulationStakes[user];
        if (!s.exists) revert NoStake();
        if (amount > s.amount) revert InsufficientStake();

        s.amount -= amount;
        if (s.amount == 0) {
            if (lockedByBond[user]) lockedByBond[user] = false;
            if (depositType == DepositType.Conception) {
                delete stakes[user];
            } else {
                delete postCopulationStakes[user];
            }
        }

        if (!evolveToken.transfer(to, amount)) revert TransferFailed();
    }

    function transferStake(address from, address to, uint256 amount, DepositType depositType) external onlyBondManager nonReentrant {
        StakeInfo storage s = depositType == DepositType.Conception ? stakes[from] : postCopulationStakes[from];
        if (!s.exists) revert NoStake();
        if (amount > s.amount) revert InsufficientStake();

        s.amount -= amount;
        if (s.amount == 0) {
            if (lockedByBond[from]) lockedByBond[from] = false;
            if (depositType == DepositType.Conception) {
                delete stakes[from];
            } else {
                delete postCopulationStakes[from];
            }
        }

        if (!evolveToken.transfer(to, amount)) revert TransferFailed();
        emit StakeTransferred(from, to, amount, depositType);
    }

    function getStake(address user) external view returns (uint256 amount, uint256 unlockTime, bool isLocked, bool exists) {
        StakeInfo storage s = stakes[user];
        return (s.amount, s.unlockTime, lockedByBond[user], s.exists);
    }

    function getPostCopulationStake(address user) external view returns (uint256 amount, uint256 unlockTime, bool isLocked, bool exists) {
        StakeInfo storage s = postCopulationStakes[user];
        return (s.amount, s.unlockTime, lockedByBond[user], s.exists);
    }

    // Check if a man can view a woman's profile based on his stake and her requirements
    function canManViewProfile(address man, address woman, DepositType depositType) external view returns (bool) {
        WomanRequirements storage req = womanRequirements[woman];
        if (!req.exists) return true; // No requirements set, anyone can view

        uint256 requiredAmount = depositType == DepositType.Conception ? req.conceptionRequired : req.postCopulationRequired;
        if (requiredAmount == 0) return true; // No requirement for this type

        StakeInfo storage s = depositType == DepositType.Conception ? stakes[man] : postCopulationStakes[man];
        if (!s.exists) return false;

        return s.amount >= requiredAmount;
    }

    // Get total stake across both types for governance
    function getTotalStake(address user) external view returns (uint256 totalAmount) {
        totalAmount = 0;
        if (stakes[user].exists) totalAmount += stakes[user].amount;
        if (postCopulationStakes[user].exists) totalAmount += postCopulationStakes[user].amount;
    }
}

src/Governance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IGovVoting {
    function calculateWeight(address user) external view returns (uint256);
    function receivedVotes(address user) external view returns (uint256);
}

interface IERC20Min {
    function balanceOf(address account) external view returns (uint256);
}

interface IEvolveFund {
    function getStake(address user) external view returns (uint256 amount, uint256 unlockTime, bool isLocked, bool exists);
}

interface IBondManager {
    function getChildrenCount(address user) external view returns (uint256);
    function getTotalMothers() external view returns (uint256);
    function getTotalFathers() external view returns (uint256);
}

contract Governance is Ownable, ReentrancyGuard {
    struct Proposal {
        uint256 id;
        string description;
        address creator;
        uint256 totalWeightFor;
        uint256 totalWeightAgainst;
        uint256 deadline;
        uint256 quorumWeight;
        bool executed;
        bool canceled;
        uint256 executionTime;
        ProposalType proposalType;
    }

    enum ProposalType { General, Implementation, Amendment }

    struct ImplementationProposal {
        uint256 proposalId;
        string title;
        string description;
        string status; // "proposed", "approved", "in_progress", "completed", "rejected"
        uint256 createdAt;
        uint256 completedAt;
        address[] contributors;
    }

    struct Amendment {
        uint256 id;
        uint256 proposalId;
        address creator;
        string description;
        uint256 votesFor;
        uint256 votesAgainst;
        bool executed;
    }

    mapping(uint256 => Proposal) private _proposals;
    mapping(uint256 => mapping(address => bool)) private _hasVoted;
    mapping(uint256 => address[]) private _voters;
    mapping(address => uint256) private _proposalCount;
    mapping(uint256 => mapping(address => uint256)) private _voteWeights;

    // Implementation proposals tracking
    mapping(uint256 => ImplementationProposal) public implementationProposals;
    uint256 private _nextImplProposalId;

    // Amendments to proposals
    mapping(uint256 => Amendment) public amendments;
    mapping(uint256 => uint256[]) public proposalAmendments;
    uint256 private _nextAmendmentId;

    // Project description in multiple languages
    mapping(string => string) public projectDescriptions;
    string[] public supportedLanguages;

    // Features tracking
    struct Feature {
        string name;
        string description;
        bool implemented;
        uint256 implementedAt;
        string language; // Primary language for this feature
    }

    mapping(string => Feature) public features;
    string[] public featureNames;
    mapping(string => bool) public featureExists;

    enum Gender { Unknown, Male, Female }

    IGovVoting public voting;
    IERC20Min public evolveToken;
    IEvolveFund public evolveFund;
    IBondManager public bondManager;

    mapping(address => Gender) public genderOf;

    uint256 public constant VOTING_PERIOD = 7 days;
    uint256 public constant TIMELOCK_DELAY = 2 days;
    uint256 public constant QUORUM_PERCENTAGE = 40;
    uint256 public constant MIN_VOTERS_TO_EXECUTE = 10;

    uint256 public constant RECURSIVE_BP = 3000;
    uint256 public constant CHILDREN_BP = 4000;
    uint256 public constant TOKEN_BP = 3000;
    uint256 public constant TOTAL_BP = 10000;

    event ProposalCreated(uint256 indexed id, string description, address indexed creator, uint256 deadline, uint256 quorumWeight);
    event VoteCast(uint256 indexed proposalId, address indexed voter, bool support, uint256 weight);
    event ProposalExecuted(uint256 indexed id);
    event ProposalCanceled(uint256 indexed id);
    event ProposalQueued(uint256 indexed id, uint256 executionTime);
    event GovContractsSet(address indexed voting, address indexed evolveToken);
    event GenderSet(address indexed user, Gender gender);
    event ImplementationProposalCreated(uint256 indexed id, string title, address indexed creator);
    event ImplementationProposalStatusChanged(uint256 indexed id, string status);
    event AmendmentCreated(uint256 indexed id, uint256 indexed proposalId, address indexed creator);
    event AmendmentVoted(uint256 indexed amendmentId, address indexed voter, bool support);
    event ProjectDescriptionUpdated(string language, string description);
    event FeatureAdded(string name, string description, string language);
    event FeatureStatusChanged(string name, bool implemented);

    error VotingEnded();
    error VotingNotEnded();
    error AlreadyVoted();
    error ProposalNotExecutable();
    error ProposalWasCanceled();
    error InsufficientVoters();
    error InvalidProposal();
    error QuorumNotReached();
    error TimelockNotExpired();
    error AlreadyQueued();
    error ZeroAddress();
    error UnknownGender();
    error InvalidImplementationProposal();
    error InvalidAmendment();
    error AmendmentAlreadyVoted();
    error FeatureAlreadyExists();
    error FeatureNotFound();

    constructor(address initialOwner) Ownable(initialOwner) {
        // Initialize default project descriptions
        _initProjectDescriptions();
    }

    function _initProjectDescriptions() private {
        // Add initial supported languages
        supportedLanguages.push("uk");
        supportedLanguages.push("en");
        supportedLanguages.push("de");
        supportedLanguages.push("fr");
        supportedLanguages.push("es");
        supportedLanguages.push("pt");
        supportedLanguages.push("ja");
        supportedLanguages.push("ko");
        supportedLanguages.push("zh");
        supportedLanguages.push("ar");
        supportedLanguages.push("vi");
        supportedLanguages.push("hi");
        supportedLanguages.push("tr");
        supportedLanguages.push("th");
        supportedLanguages.push("id");
        supportedLanguages.push("ms");
        supportedLanguages.push("ru");

        // Default Ukrainian description
        projectDescriptions["uk"] = "EVOLVE - decentralizovana platforma dlya znayomstv z vykorystannyam blokcheyn-tekhnologij. Platforma zabezpechuje bezpeku, privatnist ta spravedlyvu ekonomiku cherez token EVOLVE.";

        // Default English description
        projectDescriptions["en"] = "EVOLVE is a decentralized dating platform using blockchain technology. The platform ensures security, privacy, and fair economy through the EVOLVE token.";
    }

    function setContracts(address _voting, address _evolveToken, address _fund, address _bondManager) external onlyOwner {
        if (_voting == address(0) || _evolveToken == address(0) || _fund == address(0) || _bondManager == address(0)) revert ZeroAddress();
        voting = IGovVoting(_voting);
        evolveToken = IERC20Min(_evolveToken);
        evolveFund = IEvolveFund(_fund);
        bondManager = IBondManager(_bondManager);
        emit GovContractsSet(_voting, _evolveToken);
    }

    function setGender(address user, Gender gender) external onlyOwner {
        genderOf[user] = gender;
        emit GenderSet(user, gender);
    }

    // ──────────────────────────────────────────────
    //  WEIGHT CALCULATION
    // ──────────────────────────────────────────────

    function calculateVoteWeight(address user) public view returns (uint256) {
        Gender g = genderOf[user];
        if (g == Gender.Unknown) revert UnknownGender();

        uint256 recursiveWeight = voting.calculateWeight(user);

        uint256 childrenWeight = _calculateChildrenWeight(user, g);

        uint256 tokenWeight = 0;
        if (g == Gender.Female) {
            uint256 balance = evolveToken.balanceOf(user);
            tokenWeight = balance / (100 * 10**18);
            if (tokenWeight > 100) tokenWeight = 100;
        } else {
            if (address(evolveFund) != address(0)) {
                (uint256 stakedAmount, , , bool exists) = evolveFund.getStake(user);
                if (exists && stakedAmount > 0) {
                    tokenWeight = stakedAmount / (100 * 10**18);
                    if (tokenWeight > 100) tokenWeight = 100;
                }
            }
        }

        // 30% tokens + 30% recursive reputation + 40% children
        uint256 total = recursiveWeight * RECURSIVE_BP
                      + childrenWeight * CHILDREN_BP
                      + tokenWeight * TOKEN_BP;

        return total / 100;
    }

    function _calculateChildrenWeight(address user, Gender g) private view returns (uint256) {
        if (address(bondManager) == address(0)) return 0;

        uint256 userChildren = bondManager.getChildrenCount(user);
        if (userChildren == 0) return 0;

        uint256 totalPeers;
        if (g == Gender.Female) {
            totalPeers = bondManager.getTotalMothers();
        } else {
            totalPeers = bondManager.getTotalFathers();
        }

        if (totalPeers == 0) return 0;

        return (userChildren * 100) / totalPeers;
    }

    // ──────────────────────────────────────────────
    //  PROPOSAL LIFECYCLE
    // ──────────────────────────────────────────────

    function createProposal(string memory description) public returns (uint256) {
        return _createProposalWithType(description, ProposalType.General);
    }

    function createProposalWithAmendment(string memory description) external returns (uint256) {
        return _createProposalWithType(description, ProposalType.Amendment);
    }

    function _createProposalWithType(string memory description, ProposalType pType) internal returns (uint256) {
        uint256 proposalId = _proposalCount[msg.sender]++;

        _proposals[proposalId] = Proposal({
            id: proposalId,
            description: description,
            creator: msg.sender,
            totalWeightFor: 0,
            totalWeightAgainst: 0,
            deadline: block.timestamp + VOTING_PERIOD,
            quorumWeight: 0,
            executed: false,
            canceled: false,
            executionTime: 0,
            proposalType: pType
        });

        emit ProposalCreated(proposalId, description, msg.sender, block.timestamp + VOTING_PERIOD, 0);
        return proposalId;
    }

    function vote(uint256 proposalId, bool support) external nonReentrant {
        Proposal storage proposal = _proposals[proposalId];
        if (proposal.creator == address(0) && proposal.id == 0) revert InvalidProposal();
        if (proposal.canceled) revert ProposalWasCanceled();
        if (block.timestamp > proposal.deadline) revert VotingEnded();
        if (_hasVoted[proposalId][msg.sender]) revert AlreadyVoted();

        uint256 weight = calculateVoteWeight(msg.sender);

        _hasVoted[proposalId][msg.sender] = true;
        _voters[proposalId].push(msg.sender);
        _voteWeights[proposalId][msg.sender] = weight;

        if (support) {
            proposal.totalWeightFor += weight;
        } else {
            proposal.totalWeightAgainst += weight;
        }

        if (proposal.quorumWeight == 0) {
            proposal.quorumWeight = (weight * QUORUM_PERCENTAGE) / 100;
            if (proposal.quorumWeight < 10) proposal.quorumWeight = 10;
        }

        emit VoteCast(proposalId, msg.sender, support, weight);
    }

    function queueProposal(uint256 proposalId) external onlyOwner {
        Proposal storage proposal = _proposals[proposalId];
        if (proposal.executed) revert ProposalNotExecutable();
        if (proposal.canceled) revert ProposalWasCanceled();
        if (block.timestamp <= proposal.deadline) revert VotingNotEnded();
        if (_voters[proposalId].length < MIN_VOTERS_TO_EXECUTE) revert InsufficientVoters();
        if (proposal.totalWeightFor < proposal.quorumWeight) revert QuorumNotReached();
        if (proposal.executionTime != 0) revert AlreadyQueued();

        proposal.executionTime = block.timestamp + TIMELOCK_DELAY;
        emit ProposalQueued(proposalId, proposal.executionTime);
    }

    function executeProposal(uint256 proposalId) external onlyOwner nonReentrant {
        Proposal storage proposal = _proposals[proposalId];
        if (proposal.executed) revert ProposalNotExecutable();
        if (proposal.canceled) revert ProposalWasCanceled();
        if (proposal.executionTime == 0) revert ProposalNotExecutable();
        if (block.timestamp < proposal.executionTime) revert TimelockNotExpired();

        proposal.executed = true;
        emit ProposalExecuted(proposalId);
    }

    function cancelProposal(uint256 proposalId) external {
        Proposal storage proposal = _proposals[proposalId];
        if (proposal.executed) revert ProposalNotExecutable();
        if (msg.sender != proposal.creator && msg.sender != owner()) revert InvalidProposal();

        proposal.canceled = true;
        emit ProposalCanceled(proposalId);
    }

    // ──────────────────────────────────────────────
    //  VIEW
    // ──────────────────────────────────────────────

    function getProposal(uint256 proposalId) external view returns (Proposal memory) {
        return _proposals[proposalId];
    }

    function hasVoted(uint256 proposalId, address voter) external view returns (bool) {
        return _hasVoted[proposalId][voter];
    }

    function getVoteWeight(uint256 proposalId, address voter) external view returns (uint256) {
        return _voteWeights[proposalId][voter];
    }

    function getProposalCount(address creator) external view returns (uint256) {
        return _proposalCount[creator];
    }

    function getVoters(uint256 proposalId) external view returns (address[] memory) {
        return _voters[proposalId];
    }

    function getVoteCount(uint256 proposalId) external view returns (uint256 forVotes, uint256 againstVotes) {
        Proposal storage proposal = _proposals[proposalId];
        return (proposal.totalWeightFor, proposal.totalWeightAgainst);
    }

    // ──────────────────────────────────────────────
    //  PROJECT DESCRIPTION MANAGEMENT
    // ──────────────────────────────────────────────

    function setProjectDescription(string calldata language, string calldata description) external onlyOwner {
        projectDescriptions[language] = description;

        // Add to supported languages if not exists
        bool found = false;
        for (uint256 i = 0; i < supportedLanguages.length; i++) {
            if (keccak256(bytes(supportedLanguages[i])) == keccak256(bytes(language))) {
                found = true;
                break;
            }
        }
        if (!found) {
            supportedLanguages.push(language);
        }

        emit ProjectDescriptionUpdated(language, description);
    }

    function getProjectDescription(string calldata language) external view returns (string memory) {
        return projectDescriptions[language];
    }

    function getSupportedLanguages() external view returns (string[] memory) {
        return supportedLanguages;
    }

    // ──────────────────────────────────────────────
    //  IMPLEMENTATION PROPOSALS
    // ──────────────────────────────────────────────

    function createImplementationProposal(
        string calldata title,
        string calldata description
    ) external returns (uint256) {
        uint256 proposalId = createProposal(description);

        uint256 implId = _nextImplProposalId++;
        implementationProposals[implId] = ImplementationProposal({
            proposalId: proposalId,
            title: title,
            description: description,
            status: "proposed",
            createdAt: block.timestamp,
            completedAt: 0,
            contributors: new address[](0)
        });

        // Update proposal type
        _proposals[proposalId].proposalType = ProposalType.Implementation;

        emit ImplementationProposalCreated(implId, title, msg.sender);
        return implId;
    }

    function updateImplementationStatus(uint256 implId, string calldata status) external onlyOwner {
        ImplementationProposal storage impl = implementationProposals[implId];
        if (impl.proposalId == 0) revert InvalidImplementationProposal();

        impl.status = status;
        if (keccak256(bytes(status)) == keccak256(bytes("completed"))) {
            impl.completedAt = block.timestamp;
        }

        emit ImplementationProposalStatusChanged(implId, status);
    }

    function addContributor(uint256 implId, address contributor) external onlyOwner {
        ImplementationProposal storage impl = implementationProposals[implId];
        if (impl.proposalId == 0) revert InvalidImplementationProposal();
        impl.contributors.push(contributor);
    }

    // ──────────────────────────────────────────────
    //  AMENDMENTS TO PROPOSALS
    // ──────────────────────────────────────────────

    function createAmendment(
        uint256 proposalId,
        string calldata description
    ) external returns (uint256) {
        Proposal storage proposal = _proposals[proposalId];
        if (proposal.creator == address(0) && proposal.id == 0) revert InvalidProposal();
        if (proposal.executed) revert ProposalNotExecutable();

        uint256 amendmentId = _nextAmendmentId++;
        amendments[amendmentId] = Amendment({
            id: amendmentId,
            proposalId: proposalId,
            creator: msg.sender,
            description: description,
            votesFor: 0,
            votesAgainst: 0,
            executed: false
        });

        proposalAmendments[proposalId].push(amendmentId);
        emit AmendmentCreated(amendmentId, proposalId, msg.sender);
        return amendmentId;
    }

    function voteOnAmendment(uint256 amendmentId, bool support) external nonReentrant {
        Amendment storage amendment = amendments[amendmentId];
        if (amendment.id == 0) revert InvalidAmendment();
        if (amendment.executed) revert ProposalNotExecutable();

        uint256 weight = calculateVoteWeight(msg.sender);

        if (support) {
            amendment.votesFor += weight;
        } else {
            amendment.votesAgainst += weight;
        }

        emit AmendmentVoted(amendmentId, msg.sender, support);
    }

    function executeAmendment(uint256 amendmentId) external onlyOwner {
        Amendment storage amendment = amendments[amendmentId];
        if (amendment.id == 0) revert InvalidAmendment();
        if (amendment.executed) revert ProposalNotExecutable();

        // Check if amendment has more votes for than against
        if (amendment.votesFor <= amendment.votesAgainst) revert QuorumNotReached();

        amendment.executed = true;

        // Update proposal description with amendment
        Proposal storage proposal = _proposals[amendment.proposalId];
        proposal.description = amendment.description;

        emit ProposalCanceled(amendment.proposalId); // Reuse event for amendment execution
    }

    // ──────────────────────────────────────────────
    //  FEATURES TRACKING
    // ──────────────────────────────────────────────

    function addFeature(
        string calldata name,
        string calldata description,
        string calldata language
    ) external onlyOwner {
        if (featureExists[name]) revert FeatureAlreadyExists();

        features[name] = Feature({
            name: name,
            description: description,
            implemented: false,
            implementedAt: 0,
            language: language
        });

        featureNames.push(name);
        featureExists[name] = true;

        emit FeatureAdded(name, description, language);
    }

    function markFeatureImplemented(string calldata name) external onlyOwner {
        if (!featureExists[name]) revert FeatureNotFound();

        features[name].implemented = true;
        features[name].implementedAt = block.timestamp;

        emit FeatureStatusChanged(name, true);
    }

    function getFeature(string calldata name) external view returns (Feature memory) {
        if (!featureExists[name]) revert FeatureNotFound();
        return features[name];
    }

    function getFeatures() external view returns (string[] memory) {
        return featureNames;
    }

    function getImplementedFeatures() external view returns (string[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < featureNames.length; i++) {
            if (features[featureNames[i]].implemented) count++;
        }

        string[] memory result = new string[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < featureNames.length; i++) {
            if (features[featureNames[i]].implemented) {
                result[idx] = featureNames[i];
                idx++;
            }
        }
        return result;
    }

    function getPlannedFeatures() external view returns (string[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < featureNames.length; i++) {
            if (!features[featureNames[i]].implemented) count++;
        }

        string[] memory result = new string[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < featureNames.length; i++) {
            if (!features[featureNames[i]].implemented) {
                result[idx] = featureNames[i];
                idx++;
            }
        }
        return result;
    }
}

